 ('barthel_adl','barthel-adl-0-100-v1','barthel-adl-0-100-v1',1,'b7a12993fcb05da0ffdec3938f0472f46522db7b81cbe54e3e47ab43f1237951',$questionnaire_catalog${"form":{"allowQualitativeNotes":true,"instructions":"依個案目前實際能力選擇一項。這裡先保存填答草稿，不產生正式總分、依賴等級或照顧決策。","key":"barthel_adl","questions":[{"choices":[{"label":"10 分・可自行完成上述動作","value":"independent"},{"label":"5 分・需他人協助穿脫輔具或只會用湯匙進食","value":"needs_help"},{"label":"0 分・無法自行取食或耗費時間過長","value":"unable"}],"helpText":"自己能在合理時間（約 10 秒鐘吃一口）用筷子取食眼前食物；若需進食輔具，應能自行穿脫。","id":"feeding","prompt":"進食"},{"choices":[{"label":"5 分・可以自行完成","value":"independent"},{"label":"0 分・需要他人部分或完全協助","value":"dependent"}],"id":"grooming","prompt":"個人衛生：能否自行洗手、刷牙、洗臉及梳頭？"},{"choices":[{"label":"10 分・可自行完成上述動作","value":"independent"},{"label":"5 分・需協助平衡、整理衣服或使用衛生紙","value":"needs_help"},{"label":"0 分・無法自行完成","value":"dependent"}],"id":"toilet_use","prompt":"上廁所：能否自行上下馬桶、穿脫衣服、不弄髒衣服並使用衛生紙清潔？"},{"choices":[{"label":"5 分・能獨立完成","value":"independent"},{"label":"0 分・需要他人協助","value":"dependent"}],"id":"bathing","prompt":"洗澡：能否獨立完成盆浴或沐浴，且不需別人在旁？"},{"choices":[{"label":"10 分・能自行完成","value":"independent"},{"label":"5 分・在他人協助下可自行完成一半以上","value":"needs_help"},{"label":"0 分・不會自行完成","value":"unable"}],"id":"dressing","prompt":"穿脫衣服：能否自行穿脫衣服、鞋子，扣釦子、拉拉鍊或綁鞋帶？"},{"choices":[{"label":"10 分・不會失禁，能自行灌腸或使用塞劑","value":"continent"},{"label":"5 分・偶爾失禁（每週不超過一次），需協助灌腸或塞劑","value":"occasional_accident"},{"label":"0 分・失禁，無法自行控制且需他人處理","value":"incontinent"}],"id":"bowels","prompt":"大便控制：最近一週能否控制排便？"},{"choices":[{"label":"10 分・能自行控制或使用並清潔尿套、尿袋","value":"continent"},{"label":"5 分・偶爾失禁、尿急或需協助處理尿套","value":"occasional_accident"},{"label":"0 分・失禁，無法自行控制且需他人處理","value":"incontinent"}],"id":"bladder","prompt":"小便控制：最近一週能否控制排尿，或自行使用並清潔尿套、尿袋？"},{"choices":[{"label":"15 分・可獨立行走 50 公尺以上","value":"independent"},{"label":"10 分・需他人稍微扶持或口頭指導，方可行走 50 公尺以上","value":"walks_with_help"},{"label":"5 分・不能行走，但可操作並自行推輪椅 50 公尺以上","value":"wheelchair_independent"},{"label":"0 分・無法自行行走，需他人推輪椅","value":"immobile"}],"id":"mobility","prompt":"平地行走：使用或不使用輔具，能否在平地行走 50 公尺以上？"},{"choices":[{"label":"10 分・可自行上下樓梯，可使用扶手或拐杖等輔具","value":"independent"},{"label":"5 分・需他人協助或監督","value":"needs_help"},{"label":"0 分・無法上下樓梯","value":"unable"}],"id":"stairs","prompt":"上下樓梯：能否自行上下樓梯？"},{"choices":[{"label":"15 分・整個過程可獨立完成","value":"independent"},{"label":"10 分・移動時需要稍微協助、提醒或安全監督","value":"minor_help"},{"label":"5 分・可以自行坐起，但起身或移動時需要他人協助","value":"major_help"},{"label":"0 分・不會自行移動","value":"unable"}],"id":"transfers","prompt":"上下床或椅子：能否自行完成床椅間移位？"}],"scoreVersionId":"barthel-adl-0-100-v1","sourceLabel":"衛生福利部中央健康保險署：巴氏量表","sourceUrl":"https://www.nhi.gov.tw/ch/dl-44088-51678e4acbec4bc7830e55033aaf8415-1.pdf","title":"Barthel ADL","version":"barthel-adl-0-100-v1"},"formKey":"barthel_adl","formVersion":"barthel-adl-0-100-v1","ruleRevision":1,"ruleVersion":"barthel-adl-0-100-v1","rules":{"answerAlertTable":[],"context":[],"disclaimer":"本結果只重現指定版本的量表計分，不構成診斷、醫囑或自動處置；應由具權限人員結合完整資料判讀。","items":[{"allowNotApplicable":false,"choices":[{"points":0,"value":"unable"},{"points":5,"value":"needs_help"},{"points":10,"value":"independent"}],"id":"feeding","label":"進食","required":true},{"allowNotApplicable":false,"choices":[{"points":0,"value":"dependent"},{"points":5,"value":"independent"}],"id":"bathing","label":"洗澡","required":true},{"allowNotApplicable":false,"choices":[{"points":0,"value":"dependent"},{"points":5,"value":"independent"}],"id":"grooming","label":"個人衛生","required":true},{"allowNotApplicable":false,"choices":[{"points":0,"value":"unable"},{"points":5,"value":"needs_help"},{"points":10,"value":"independent"}],"id":"dressing","label":"穿脫衣物","required":true},{"allowNotApplicable":false,"choices":[{"points":0,"value":"incontinent"},{"points":5,"value":"occasional_accident"},{"points":10,"value":"continent"}],"id":"bowels","label":"排便控制","required":true},{"allowNotApplicable":false,"choices":[{"points":0,"value":"incontinent"},{"points":5,"value":"occasional_accident"},{"points":10,"value":"cont