 ('lawton_iadl','lawton-iadl-8-domain-expanded-v1','lawton-iadl-8-domain-expanded-v2',2,'a558f9069b6ad4156e95ded03858fcf0c72ab9605cdcf9ba114cd91c15dd5f9c',$questionnaire_catalog${"form":{"allowQualitativeNotes":true,"instructions":"逐項記錄目前能力；候選分數依 Lawton 原表的選項權重計算，尚待人工核准，不作正式分級或照顧決策。","key":"lawton_iadl","questions":[{"choices":[{"label":"自動自發使用電話、查電話號碼並撥號","value":"telephone_dials_numbers"},{"label":"只會撥幾個熟知的電話","value":"telephone_familiar_numbers"},{"label":"會接電話，但不會撥號","value":"telephone_answer_only"},{"label":"完全不會使用電話","value":"telephone_unable"}],"helpText":"請選擇最符合目前能力的一項；分數僅為此固定版本的功能參考，不取代專業判讀。","id":"telephone","prompt":"使用電話的能力"},{"choices":[{"label":"獨立處理所有購物需求","value":"shopping_independent_all"},{"label":"可以獨立執行小額購買","value":"shopping_small_items_only"},{"label":"每次上街購物都需要有人陪伴","value":"shopping_accompanied"},{"label":"完全不會上街購物","value":"shopping_unable"}],"helpText":"請選擇最符合目前能力的一項；分數僅為此固定版本的功能參考，不取代專業判讀。","id":"shopping","prompt":"上街購物"},{"choices":[{"label":"獨立計畫、烹煮並擺設一頓適當的飯菜","value":"meal_independent"},{"label":"若備好所有材料，可做一頓適當的飯菜","value":"meal_prepared_ingredients"},{"label":"會加熱並擺設已做好的飯菜，或做飯但不夠充分","value":"meal_reheat_or_inadequate"},{"label":"需要別人把飯菜煮好、擺好","value":"meal_needs_prepared"}],"helpText":"請選擇最符合目前能力的一項；分數僅為此固定版本的功能參考，不取代專業判讀。","id":"food_preparation","prompt":"做飯"},{"choices":[{"label":"能單獨處理家事，或偶爾需要協助較重家事","value":"housework_independent"},{"label":"能做較輕的家事，例如洗碗、鋪床、疊被","value":"housework_light_tasks"},{"label":"能做較輕家事，但清潔程度未達可接受程度","value":"housework_below_standard"},{"label":"所有家事都需要別人協助","value":"housework_all_help"},{"label":"完全不會做家事","value":"housework_unable"}],"helpText":"請選擇最符合目前能力的一項；分數僅為此固定版本的功能參考，不取代專業判讀。","id":"housekeeping","prompt":"做家事"},{"choices":[{"label":"會洗所有個人衣物","value":"laundry_all"},{"label":"會洗小件衣物，例如襪子、褲襪","value":"laundry_small_items"},{"label":"所有衣物都要由別人代洗","value":"laundry_needs_help"}],"helpText":"請選擇最符合目前能力的一項；分數僅為此固定版本的功能參考，不取代專業判讀。","id":"laundry","prompt":"洗衣"},{"choices":[{"label":"能自己搭乘公共交通或自己開車","value":"transport_public_or_drive"},{"label":"能自己搭計程車，但不會搭公共交通工具","value":"transport_taxi_only"},{"label":"有人協助或陪伴時，可以搭公共交通工具","value":"transport_with_companion"},{"label":"只能在別人協助下搭計程車或私用車","value":"transport_private_with_help"},{"label":"完全不能出門","value":"transport_unable_to_leave"}],"helpText":"請選擇最符合目前能力的一項；分數僅為此固定版本的功能參考，不取代專業判讀。","id":"transportation","prompt":"使用交通工具"},{"choices":[{"label":"能自行在正確時間服用正確藥物","value":"medication_independent"},{"label":"若事先備妥藥物分量，可以自行服用","value":"medication_prepared"},{"label":"不能自己負責服藥","value":"medication_needs_help"}],"helpText":"請選擇最符合目前能力的一項；分數僅為此固定版本的功能參考，不取代專業判讀。","id":"medications","prompt":"自己負責用藥"},{"choices":[{"label":"能獨立做預算、付帳單、處理銀行事務並清楚掌握收支","value":"finances_independent"},{"label":"能處理日常購買，但需協助銀行往來或大宗購買","value":"finances_daily_only"},{"label":"不能處理錢財","value":"finances_unable"}],"helpText":"請選擇最符合目前能力的一項；分數僅為此固定版本的功能參考，不取代專業判讀。","id":"finances","prompt":"財務管理"}],"scoreVersionId":"lawton-iadl-8-domain-expanded-v2","sourceLabel":"題目：衛福部《失智症診療手冊》附錄五；候選權重：NYU HIGN 2019 Lawton 原表","sourceUrl":"https://hign.org/sites/default/files/2020-06/Try_This_General_Assessment_23.pdf","title":"IADL 工具性日常生活活動","version":"lawton-iadl-8-domain-expanded-v1"},"formKey":"lawton_iadl","formVersion":"lawton-iadl-8-domain-expanded-v1","ruleRevision":2,"ruleVersion":"lawton-iadl-8-domain-expanded-v2","rules":{"answerAlertTable":[],"context":[],"disclaimer":"本結果只重現指定版本的量表計分，不構成診斷、醫囑或自動處置；應由具權限人員結合完整資料判讀。","items":[{"allowNotApplicable":false,"choices":[{"points":1,"value":"telephone_dials_numbers"},{"points":1,"value":"telephone_familiar_numbers"},{"points":1,"value":"telephone_answer_only"},{"points":0,"value":"telephone_unable"}],"id":"telephone","label":"使用電話","required":true},{"allowNotApplicable":false,"choices":[{"points":1,"value":"shopping_independent_all"},{"points":0,"value":"shopping_small_items_only"},{"points":0,"value":"shopping_accompanied"},{"points":0,"value":"shopping_unable"}],"id":"shopping","label":"上街購物","required":true},{"al